+     *
+     * <p>Uploads remain caller-owned; the document and all opened streams/readers are closed on
+     * success or failure. Decoding is sequential and any failed input aborts the whole book.
+     *
+     * @throws IllegalArgumentException if the batch is absent, empty, or contains null/empty
+     *     uploads
+     * @throws IOException if any image or TIFF frame cannot be decoded or the PDF cannot be saved
+     */
+    public byte[] createColoringBook(
+            MultipartFile[] files, CustomPDFDocumentFactory pdfDocumentFactory) throws IOException {
+        if (files == null || files.length == 0) {
